import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

custom_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_clamp_softmax_scale_kernel(
    const float* input,
    float* output,
    float clamp_min,
    float clamp_max,
    int num_elements,
    int channels,
    int spatial_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int spatial_idx = idx % spatial_size;
    int batch_channel = idx / spatial_size;
    int channel = batch_channel % channels;
    int batch = batch_channel / channels;

    float max_val = -INFINITY;
    float sum_exp = 0.0f;
    float buffer[1024];

    // Load and clamp values for all channels at this spatial position
    for(int c = 0; c < channels; c++) {
        int ch_idx = (batch * channels + c) * spatial_size + spatial_idx;
        float val = input[ch_idx];
        buffer[c] = fmaxf(fminf(val, clamp_max), clamp_min);
        max_val = fmaxf(max_val, buffer[c]);
    }

    // Compute sum of exponentials
    for(int c = 0; c < channels; c++) {
        sum_exp += expf(buffer[c] - max_val);
    }

    // Write final scaled softmax result
    int out_idx = (batch * channels + channel) * spatial_size + spatial_idx;
    output[out_idx] = expf(buffer[channel] - max_val) / sum_exp * 2.0f;
}

torch::Tensor fused_clamp_softmax_scale_cuda(
    torch::Tensor input,
    float clamp_min,
    float clamp_max
) {
    auto dims = input.sizes();
    int batch_size = dims[0];
    int channels = dims[1];
    int spatial_size = input.numel() / (batch_size * channels);

    auto output = torch::empty_like(input);
    int num_elements = batch_size * channels * spatial_size;

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    fused_clamp_softmax_scale_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        clamp_min,
        clamp_max,
        num_elements,
        channels,
        spatial_size
    );

    return output;
}
"""

cpp_source = "torch::Tensor fused_clamp_softmax_scale_cuda(torch::Tensor input, float clamp_min, float clamp_max);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=cpp_source,
    cuda_sources=custom_kernel_source,
    functions=['fused_clamp_softmax_scale_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, pool_kernel_size, clamp_min, clamp_max):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size, 
                                                stride=stride, padding=padding, 
                                                output_padding=output_padding)
        self.avg_pool = nn.AvgPool3d(pool_kernel_size)
        self.clamp_min = clamp_min
        self.clamp_max = clamp_max

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.avg_pool(x)
        x = fused_ops.fused_clamp_softmax_scale_cuda(x.contiguous(), self.clamp_min, self.clamp_max)
        return x
